function dijkstra(start, n, graph) {
    const INF = Infinity;
    const dist = new Array(n + 1).fill(INF);
    dist[start] = 0;

    // 최소 힙: [거리, 노드]
    const pq = [[0, start]];

    while (pq.length > 0) {
        pq.sort((a, b) => a[0] - b[0]);
        const [curDist, curNode] = pq.shift();

        if (curDist > dist[curNode]) continue; // 이미 처리된 노드

        for (const [next, weight] of graph[curNode]) {
            if (dist[curNode] + weight < dist[next]) {
                dist[next] = dist[curNode] + weight;
                pq.push([dist[next], next]);
            }
        }
    }
    return dist;
}

function main() {
    const n = 5;
    const graph = Array.from({ length: n + 1 }, () => []);

    // [도착 노드, 가중치]
    graph[1].push([2, 2]);
    graph[1].push([3, 5]);
    graph[2].push([3, 1]);
    graph[2].push([4, 7]);
    graph[3].push([4, 3]);
    graph[4].push([5, 1]);

    const dist = dijkstra(1, n, graph);
    for (let i = 1; i <= n; i++)
        console.log(`1 -> ${i} : ${dist[i]}`);
    // 1->1:0, 1->2:2, 1->3:3, 1->4:6, 1->5:7
}

main();
